#include <string.h>

void greet(const char *name) {
    char buf[64];
    if (strlen(name) >= sizeof(buf)) {
        return;
    }
    snprintf(buf, sizeof(buf), "Hello %s", name);
    puts(buf);
}

#include <stdlib.h>
#include <stdint.h>

int sum_items(const int *items, size_t n) {
    if (n > SIZE_MAX / sizeof(int) || items == NULL) {
        return -1;
    }
    int total = 0;
    for (size_t i = 0; i < n; i++) {
        total += items[i];
    }
    return total;
}
